SELECT * FROM (
SELECT a.name, COUNT(pa.arxiv_id) AS paper_count, GROUP_CONCAT(pa.arxiv_id || ': ' || p.title, ' | ') AS papers FROM authors a JOIN paper_authors pa ON a.author_id = pa.author_id JOIN papers p ON pa.arxiv_id = p.arxiv_id GROUP BY a.author_id, a.name HAVING COUNT(pa.arxiv_id) > 1 ORDER BY paper_count DESC, a.name ASC
) LIMIT 51

SELECT * FROM (
SELECT COUNT(*) AS total_multi_paper_authors FROM (SELECT author_id FROM paper_authors GROUP BY author_id HAVING COUNT(arxiv_id) > 1)
) LIMIT 51

SELECT * FROM (
SELECT a.name, COUNT(pa.arxiv_id) AS paper_count, GROUP_CONCAT(pa.arxiv_id, ', ') AS paper_ids FROM authors a JOIN paper_authors pa ON a.author_id = pa.author_id GROUP BY a.author_id, a.name HAVING COUNT(pa.arxiv_id) >= 4 ORDER BY paper_count DESC, a.name ASC
) LIMIT 51
